cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# Exact cover one 2x2 and remaining 4 L triominoes; list solutions and shapes
from itertools import combinations
squares=[frozenset({(r,c),(r+1,c),(r,c+1),(r+1,c+1)}) for r in range(3) for c in range(6) if {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}<=cells]
Ls=[]
for r in range(4):
 for c in range(6):
  for subset in combinations([(r,c),(r+1,c),(r,c+1),(r+1,c+1)],3):
   if set(subset)<=cells and frozenset(subset) not in Ls: Ls.append(frozenset(subset))
sol=[]
def rec(rem, chosen):
 if not rem:
  if len(chosen)==4: sol.append(chosen)
  return
 if len(chosen)>=4:return
 p=min(rem)
 for x in Ls:
  if p in x and x<=rem:rec(rem-x,chosen+[x])
for sq in squares:
 sol=[];rec(cells-sq,[])
 print('square',sq,'solutions',len(sol))
 if sol: print(sol[:3])
